// 1. Príprava na párty (Tmavá stena)
wall.color = "#2c3e50";
wall.borders = 15;
// Príprava Creepera
creeper.visible = true;
creeper.text = "PÁRTY!";
creeper.width = 120;
creeper.height = 240;
// Tieto premenné si budú pamätať aktuálny stav
let uhol = 0;
let cas = 0;
let zoznamFarieb = ["#FF6B6B", "#4ECDC4", "#FFD93D", "#9b59b6", "#2ecc71"];
let indexFarby = 0;
// 2. RÝCHLA ANIMÁCIA: Každých 50 milisekúnd (veľmi rýchlo) sa stane toto:
setInterval(function() {
    cas = cas + 0.1;
    
    // Zväčšujeme uhol, takže sa Creeper neustále točí
    uhol = uhol + 5;
    creeper.angle = uhol;
    
    // Matematické kúzlo (Sinus a Kosinus) na pohyb v kruhu/osmičke!
    creeper.x = Math.sin(cas) * 150; 
    creeper.y = Math.cos(cas * 2) * 100;
    
    // Tancujúce nohy - zapínajú a vypínajú sa
    if (uhol % 30 === 0) {
        creeper.legs = !creeper.legs; 
    }
}, 50);
// 3. POMALÁ ANIMÁCIA: Každú sekundu (1000 ms) meníme farbu
setInterval(function() {
    // Posunieme sa na ďalšiu farbu v zozname
    indexFarby = indexFarby + 1;
    
    // Ak sme na konci zoznamu, ideme odznova
    if (indexFarby >= zoznamFarieb.length) {
        indexFarby = 0;
    }
    
    // Nastavíme novú farbu Creeperovi
    creeper.color = zoznamFarieb[indexFarby];
    
    // Vypíšeme do našej novej farebnej konzoly!
    console.log("Creeper zmenil farbu na: ", creeper.color, "!");
}, 1000);

